#!/usr/bin/env node
"use strict";

/**
 * Downloads Working Women of Tampa Bay's official Wild Apricot RSS feed of
 * upcoming events and writes the ones in a known Hillsborough-area city as
 * Opportunity records (see SPEC.md's Data Model) to public/events-feed.json.
 *
 * Source (official, public): https://workingwomenoftampabay.com/events/RSS
 * (linked from their events page, https://workingwomenoftampabay.com/events,
 * and generated by their Wild Apricot membership software).
 *
 * Privacy note: the feed's <description> text is free-form event copy that
 * routinely names organizers, hosts, and speakers (e.g. "Kiona Singleton
 * with Singleton Advisory Partners will facilitate..."). This script never
 * reads that field. It only reads each item's <title>, <pubDate>, and
 * <link> — none of which have contained a personal name in samples checked
 * so far. The event's city is matched only against the title, using the
 * same Hillsborough city list the advisor profile checklist uses (plus a
 * short list of Tampa neighborhood names, since the feed covers the wider
 * Tampa Bay area). If a title doesn't confidently match a known city, the
 * event is skipped rather than guessed from the description. The feed gives
 * no venue or ZIP at all for any event, so those are always left blank
 * here — they are not invented.
 */

import fs from "fs";
import path from "path";
import https from "https";
import { fileURLToPath } from "url";
import { HILLSBOROUGH_CITIES, BORDER_AREA_CITIES } from "../src/hillsboroughCities.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const EVENTS_FEED_FILE = path.join(__dirname, "..", "public", "events-feed.json");

const FEED_URL = "https://workingwomenoftampabay.com/events/RSS";
const SOURCE = "wwtb-rss";
const HOSTING_ORG = "Working Women of Tampa Bay";
// Stated by the organization itself (its name and mission, repeated across
// every event description sampled) rather than scraped per event.
const AUDIENCE = "Women in business";
// The feed never states a price, and individual event pages aren't fetched
// here (that would mean scraping each one) — so cost is always unknown.
const COST = "Cost unknown";

// Tampa neighborhoods that use "Tampa" as their postal city (same reasoning
// as the comment in src/hillsboroughCities.js), extended with the ones this
// feed's event titles actually use.
const TAMPA_NEIGHBORHOODS = [
  "South Tampa",
  "Ybor City",
  "Seminole Heights",
  "Carrollwood",
  "Westchase",
  "Town 'n' Country",
  "Citrus Park",
  "Egypt Lake",
  "Davis Islands",
  "Hyde Park",
  "New Tampa",
];

// Longest name first, so "Sun City Center" matches before a shorter name
// could, and so neighborhood names are tried before the bare city they map
// to (not that it matters here, since both resolve to the same city).
const KNOWN_CITIES = [
  ...HILLSBOROUGH_CITIES.map((city) => ({ name: city, city })),
  ...BORDER_AREA_CITIES.map((city) => ({ name: city, city })),
  ...TAMPA_NEIGHBORHOODS.map((name) => ({ name, city: "Tampa" })),
].sort((a, b) => b.name.length - a.name.length);

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// Matches only against the event title (never the free-text description —
// see the privacy note above). Returns null if no known city is found,
// rather than guessing.
function matchCityFromTitle(title) {
  for (const { name, city } of KNOWN_CITIES) {
    const re = new RegExp(`\\b${escapeRegExp(name)}\\b`, "i");
    if (re.test(title)) return city;
  }
  return null;
}

function classifyEventType(title) {
  if (/coffee/i.test(title)) return "Coffee networking";
  if (/lunch/i.test(title)) return "Lunch networking";
  if (/breakfast/i.test(title)) return "Networking breakfast";
  if (/happy hour|cocktail/i.test(title)) return "Evening mixer";
  if (/workshop/i.test(title)) return "Workshop";
  return "Networking event";
}

const HTML_ENTITIES = {
  "&amp;": "&",
  "&lt;": "<",
  "&gt;": ">",
  "&quot;": '"',
  "&#39;": "'",
  "&nbsp;": " ",
};

function decodeEntities(str) {
  return str.replace(/&amp;|&lt;|&gt;|&quot;|&#39;|&nbsp;/g, (m) => HTML_ENTITIES[m]);
}

// Drops the "(DD Mon YYYY)" suffix Wild Apricot appends to every title in
// this feed — it's redundant with the separate date field.
function cleanTitle(rawTitle) {
  return decodeEntities(rawTitle)
    .replace(/\s*\(\d{1,2}\s+\w{3}\s+\d{4}\)\s*$/, "")
    .trim();
}

function fetchText(url) {
  return new Promise((resolve, reject) => {
    https
      .get(url, (res) => {
        if (res.statusCode !== 200) {
          reject(new Error(`Failed to fetch ${url}: HTTP ${res.statusCode}`));
          return;
        }
        let data = "";
        res.setEncoding("utf8");
        res.on("data", (chunk) => (data += chunk));
        res.on("end", () => resolve(data));
      })
      .on("error", reject);
  });
}

function parseRssItems(xml) {
  const itemBlocks = xml.match(/<item>([\s\S]*?)<\/item>/g) || [];
  return itemBlocks.map((block) => {
    const title = (block.match(/<title>([\s\S]*?)<\/title>/) || [])[1] || "";
    const pubDate = (block.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [])[1] || "";
    const link = (block.match(/<link>([\s\S]*?)<\/link>/) || [])[1] || "";
    return { title, pubDate: pubDate.trim(), link: link.trim() };
  });
}

// Converts a feed pubDate (UTC) to a Tampa-local YYYY-MM-DD date and HH:MM
// 24-hour time, handling the EST/EDT switch automatically.
function toEasternDateTime(utcDate) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).formatToParts(utcDate);
  const get = (type) => parts.find((p) => p.type === type).value;
  const hour = get("hour") === "24" ? "00" : get("hour");
  return { date: `${get("year")}-${get("month")}-${get("day")}`, time: `${hour}:${get("minute")}` };
}

function eventIdFromLink(link) {
  const m = link.match(/event-(\d+)/);
  return m ? `wwtb-${m[1]}` : null;
}

async function fetchEvents() {
  const xml = await fetchText(FEED_URL);
  const items = parseRssItems(xml);

  const events = [];
  for (const item of items) {
    if (!item.title || !item.pubDate || !item.link) continue;

    const city = matchCityFromTitle(item.title);
    if (!city) continue;

    const id = eventIdFromLink(item.link);
    if (!id) continue;

    const pubDate = new Date(item.pubDate);
    if (Number.isNaN(pubDate.getTime())) continue;
    const { date, time } = toEasternDateTime(pubDate);
    const eventType = classifyEventType(item.title);

    events.push({
      id,
      source: SOURCE,
      type: "event",
      name: cleanTitle(item.title),
      eventType,
      date,
      startTime: time,
      venue: "",
      city,
      zip: "",
      hostingOrg: HOSTING_ORG,
      tags: [
        { type: "audience", label: AUDIENCE },
        { type: "cost", label: COST },
        { type: "format", label: eventType },
      ],
      url: item.link,
    });
  }
  return events;
}

async function writeEventsFeedJson(events) {
  await fs.promises.mkdir(path.dirname(EVENTS_FEED_FILE), { recursive: true });
  await fs.promises.writeFile(EVENTS_FEED_FILE, JSON.stringify(events, null, 2) + "\n");
}

async function main() {
  console.log(`Fetching ${FEED_URL} ...`);
  const events = await fetchEvents();
  await writeEventsFeedJson(events);

  console.log("");
  console.log(`Found ${events.length} upcoming event(s) in a known Hillsborough-area city.`);
  console.log(`Wrote them to public/events-feed.json`);
  console.log("");
  console.log("Sample:");
  events.slice(0, 3).forEach((e, i) => {
    const tagList = e.tags.map((t) => t.label).join(", ");
    console.log(`  ${i + 1}. ${e.name} — ${e.date} ${e.startTime} — ${e.city} — ${e.hostingOrg} — [${tagList}]`);
  });
}

main().catch((err) => {
  console.error("Error:", err.message);
  process.exitCode = 1;
});
